// ============================================================
// THĂM DÒ NGUỒN ROE / ROA / NỢ / BIÊN LN - mã thử: VNM
// ratios/latest chỉ có P/E,P/B,cổ tức -> tìm endpoint khác.
// Chạy xong gửi kết quả (tab JSON) để chọn nguồn.
// ============================================================
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const Hv = { 'User-Agent': UA, 'Accept': 'application/json, text/plain, */*', 'Referer': 'https://dstock.vndirect.com.vn/' };
const H = { 'User-Agent': UA, 'Accept': 'application/json, text/plain, */*' };

const sources = [
  {
    name: 'A. VNDirect financial_models (modelType:1)',
    url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM~modelType:1&sort=reportDate:desc&size=5',
    headers: Hv,
  },
  {
    name: 'B. VNDirect financial_models (không filter phụ)',
    url: 'https://api-finfo.vndirect.com.vn/v4/financial_models?q=code:VNM&size=5',
    headers: Hv,
  },
  {
    name: 'C. VNDirect ratios (filter ROE/nợ trực tiếp)',
    url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:VNM~itemCode:51003,51004,52001,53008&sort=reportDate:desc&size=20',
    headers: Hv,
  },
  {
    name: 'D. VNDirect financial_statements',
    url: 'https://api-finfo.vndirect.com.vn/v4/financial_statements?q=code:VNM~reportType:QUARTER~modelType:1&sort=reportDate:desc&size=3',
    headers: Hv,
  },
  {
    name: 'E. SSI iboard - finance ratio',
    url: 'https://iboard-query.ssi.com.vn/statistics/company/finance-ratio?symbol=VNM',
    headers: { ...H, Referer: 'https://iboard.ssi.com.vn/' },
  },
  {
    name: 'F. Simplize - financial ratio',
    url: 'https://api.simplize.vn/api/company/financial-ratio/VNM',
    headers: H,
  },
  {
    name: 'G. Simplize - key indicators',
    url: 'https://api.simplize.vn/api/company/key-statistics/VNM',
    headers: H,
  },
];

const results = [];
for (const s of sources) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: s.url, headers: s.headers, json: false, timeout: 20000 });
    const body = typeof res === 'string' ? res : JSON.stringify(res);
    results.push({ source: s.name, status: '✅ SỐNG', sample: body.slice(0, 700) });
  } catch (e) {
    results.push({ source: s.name, status: '❌ ' + (e.message || String(e)), sample: '' });
  }
}

return results.map(r => ({ json: r }));
